import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

// @spec specs/hal-engine-config-hooks/spec.md#8
describe('ChatOrchestrator onError for Error rejections', () => {
  it('passes the original Error to onError and rethrows the same instance', async () => {
    const reason = new Error('provider failed');
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw reason;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const session: ChatSession = {
      sessionId: 'test-session',
      userId: 'user-1',
      entries: [{role: 'user', content: 'hello', timestamp: '2025-01-01T00:00:00.000Z'}],
    };
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };
    const orchestrator = createChatOrchestrator(
      provider,
      new PromptBuilder({identity: 'You are a test assistant.'}),
      undefined,
      {hooks}
    );

    const thrown = await orchestrator.processMessage(session).then(
      () => undefined,
      error => error
    );

    expect(receivedError).toBe(reason);
    expect(thrown).toBe(reason);
  });
});
